package com.weearntogether.lazygarden

import android.app.Activity
import android.os.Bundle
import android.view.View
import android.widget.Button
import android.widget.FrameLayout
import android.widget.ImageView
import android.widget.TextView
import com.weearntogether.play.LevelPlayManager
import com.weearntogether.play.R

class LazyGardenActivity : Activity() {
    private val collected=mutableMapOf<GardenTile,Int>();private val clearedObstacles=mutableMapOf<GardenObstacle,Int>();private lateinit var board:LazyGardenBoardView;private lateinit var wallet:LazyGardenWallet;private lateinit var progressStore:LazyGardenProgressStore;private lateinit var strings:LazyGardenStrings
    private var currentLevel=1;private var unlockedLevel=1;private var levelFinished=false;private var restoring=false;private var shuffleBoosters=3
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContentView(R.layout.activity_lazy_garden);strings=LazyGardenStrings(this);wallet=LazyGardenWallet(this);progressStore=LazyGardenProgressStore(this);val saved=progressStore.load();currentLevel=saved.level;unlockedLevel=saved.unlockedLevel;shuffleBoosters=saved.shuffleBoosters;board=LazyGardenBoardView(this);findViewById<FrameLayout>(R.id.lgBoardHost).addView(board,FrameLayout.LayoutParams(-1,-1));startLevel(currentLevel,saved.collected,saved.clearedObstacles,saved.movesLeft,saved.boardState,saved.obstacleState);board.onMove={r->r.tiles.forEach{(t,n)->collected[t]=(collected[t]?:0)+n};r.obstacles.forEach{(o,n)->clearedObstacles[o]=(clearedObstacles[o]?:0)+n};saveProgress();if(goalsComplete())finishLevel(true)else if(board.engine.movesLeft<=0)finishLevel(false)else updateHud()};findViewById<Button>(R.id.lgAction).setOnClickListener{handleAction()};findViewById<Button>(R.id.lgShuffle).setOnClickListener{useShuffle()};updateHud()}
    override fun onStop(){super.onStop();saveProgress();val app=applicationContext;com.weearntogether.play.CloudWorker.executor.execute{try{com.weearntogether.play.CloudProgress(app).sync(false)}catch(_:Exception){}}}
    private fun useShuffle(){if(levelFinished||restoring||shuffleBoosters<=0)return;if(board.engine.shuffleBoard()){shuffleBoosters--;saveProgress();updateHud()}}
    private fun startLevel(n:Int,restored:Map<GardenTile,Int> = emptyMap(),restoredObstacles:Map<GardenObstacle,Int> = emptyMap(),restoredMoves:Int?=null,boardState:String="",obstacleState:String=""){currentLevel=n.coerceIn(1,LazyGardenLevels.count);collected.clear();GardenTile.entries.forEach{collected[it]=restored[it]?:0};clearedObstacles.clear();GardenObstacle.entries.forEach{clearedObstacles[it]=restoredObstacles[it]?:0};board.loadLevel(LazyGardenLevels.get(currentLevel));if(boardState.isNotEmpty()&&obstacleState.isNotEmpty())board.engine.restoreState(boardState,obstacleState);restoredMoves?.let{board.engine.restoreMoves(it)};levelFinished=goalsComplete()||board.engine.movesLeft<=0;board.setInputEnabled(!levelFinished);restoring=false;updateHud()}
    private fun goalsComplete():Boolean{val l=LazyGardenLevels.get(currentLevel);return l.goals.all{(collected[it.tile]?:0)>=it.target}&&l.obstacleGoals.all{(clearedObstacles[it.obstacle]?:0)>=it.target}}
    private fun finishLevel(won:Boolean){levelFinished=true;board.setInputEnabled(false);if(won){val l=LazyGardenLevels.get(currentLevel);if(progressStore.markRewardClaimed(currentLevel)){wallet.credit(l.coinReward);if(currentLevel%5==0)shuffleBoosters++};unlockedLevel=maxOf(unlockedLevel,(currentLevel+1).coerceAtMost(LazyGardenLevels.count));saveProgress();LevelPlayManager.showLevelCompleteVideo()};updateHud()}
    private fun restorationLayerFor(level:Int):ImageView?=when((level-1)%10){0->findViewById(R.id.lgGateRestored);2->findViewById(R.id.lgFlowersRestored);4->findViewById(R.id.lgFountainRestored);6->findViewById(R.id.lgBenchRestored);8->findViewById(R.id.lgPathRestored);else->null}
    private fun showCompletedRestorationLayers(){val chapterStart=((currentLevel-1)/10)*10+1;listOf(chapterStart,chapterStart+2,chapterStart+4,chapterStart+6,chapterStart+8).forEach{level->restorationLayerFor(level)?.let{view->val visible=progressStore.isBuildTaskCompleted(level);view.visibility=if(visible)View.VISIBLE else View.INVISIBLE;view.alpha=if(visible)1f else 0f;view.scaleX=1f;view.scaleY=1f}}}
    private fun handleAction(){if(restoring||!levelFinished)return;if(!goalsComplete()){startLevel(currentLevel);saveProgress();return};val s=LazyGardenStory.get(currentLevel);if(!progressStore.isBuildTaskCompleted(currentLevel)){if(wallet.spend(s.cost)){restoring=true;updateHud();val art=findViewById<ImageView>(R.id.lgGardenArtwork);val glow=findViewById<View>(R.id.lgRestoredGlow);val feature=restorationLayerFor(currentLevel);glow.visibility=View.VISIBLE;glow.alpha=0f;feature?.apply{visibility=View.VISIBLE;alpha=0f;scaleX=.72f;scaleY=.72f};glow.animate().alpha(.8f).setDuration(350).start();art.animate().alpha(.5f).scaleX(.97f).scaleY(.97f).setDuration(350).withEndAction{progressStore.markBuildTaskCompleted(currentLevel);art.animate().alpha(1f).scaleX(1f).scaleY(1f).setDuration(650).start();glow.animate().alpha(1f).setDuration(650).start();feature?.animate()?.alpha(1f)?.scaleX(1f)?.scaleY(1f)?.setDuration(700)?.start();restoring=false;updateHud()}.start()};return};if(currentLevel<LazyGardenLevels.count){startLevel(currentLevel+1);saveProgress()}}
    private fun saveProgress()=progressStore.save(LazyGardenProgress(currentLevel,unlockedLevel,board.engine.movesLeft,collected.toMap(),clearedObstacles.toMap(),board.engine.encodeBoard(),board.engine.encodeObstacles(),shuffleBoosters))
    private fun updateHud(){val l=LazyGardenLevels.get(currentLevel);val s=LazyGardenStory.get(currentLevel);val done=progressStore.isBuildTaskCompleted(currentLevel);findViewById<TextView>(R.id.lgLevel).text=strings.level(currentLevel,LazyGardenLevels.count);findViewById<TextView>(R.id.lgMoves).text=strings.moves(board.engine.movesLeft);findViewById<TextView>(R.id.lgCoins).text=strings.coins(wallet.coins);findViewById<TextView>(R.id.lgSpeaker).text=s.speaker;findViewById<ImageView>(R.id.lgCharacter).setImageResource(if(s.speaker=="Alex")R.drawable.lg_alex else R.drawable.lg_mia);findViewById<TextView>(R.id.lgDialogue).text=if(restoring)strings.workingDialogue() else if(done)s.after else s.before;val tileGoals=l.goals.map{"${strings.tile(it.tile)} ${collected[it.tile]?:0}/${it.target}"};val obstacleGoals=l.obstacleGoals.map{"${strings.obstacle(it.obstacle)} ${clearedObstacles[it.obstacle]?:0}/${it.target}"};findViewById<TextView>(R.id.lgGoals).text=strings.goals(tileGoals+obstacleGoals);findViewById<TextView>(R.id.lgBuildTask).text=when{restoring->strings.restoring(s.buildTask);done->strings.restored(s.buildTask);else->strings.buildTask(s.buildTask,s.cost)};showCompletedRestorationLayers();restorationLayerFor(currentLevel)?.let{feature->if(restoring){feature.visibility=View.VISIBLE}else if(done){feature.visibility=View.VISIBLE;feature.alpha=1f;feature.scaleX=1f;feature.scaleY=1f}};val glow=findViewById<View>(R.id.lgRestoredGlow);glow.visibility=if(done||restoring)View.VISIBLE else View.INVISIBLE;glow.alpha=if(done)1f else if(restoring)glow.alpha else 0f;val badge=findViewById<TextView>(R.id.lgRestorationBadge);badge.visibility=if(done)View.VISIBLE else View.GONE;badge.text="✓ ${s.buildTask}";val sh=findViewById<Button>(R.id.lgShuffle);sh.text=strings.shuffle(shuffleBoosters);sh.isEnabled=!levelFinished&&!restoring&&shuffleBoosters>0;findViewById<TextView>(R.id.lgBoosterHint).text=strings.booster(shuffleBoosters);val a=findViewById<Button>(R.id.lgAction);when{restoring->{a.isEnabled=false;a.text=strings.building()};!levelFinished->{a.isEnabled=false;a.text=strings.finishToBuild()};!goalsComplete()->{a.isEnabled=true;a.text=strings.retry(currentLevel)};!done->{a.isEnabled=wallet.coins>=s.cost;a.text=strings.build(s.cost)};currentLevel<LazyGardenLevels.count->{a.isEnabled=true;a.text=strings.continueStory(currentLevel+1)};else->{a.isEnabled=false;a.text=strings.chapterDone()}}}
}
